<template><main class="page"><PageHeader :title="t('nav.custom_tools')"><template #primary><button ref="openButton" data-action="open-add-tool" @click="open">{{t('custom_tools.add')}}</button></template></PageHeader><SectionCard><article v-for="tool in tools" :key="tool.name" :data-tool="tool.name"><h3>{{tool.displayName}}</h3><p>{{tool.version}} · {{tool.category}}</p><CopyableValue :value="tool.downloadUrl"/><div><button v-if="!tool.installPath" data-action="install-tool" :disabled="!!operating[tool.name]" @click="$emit('install',tool.name)">{{t('btn.install')}}</button><ConfirmAction :title="t('custom_tools.remove_confirm')" :pending="!!operating[tool.name]" :confirm-label="t('btn.remove')" :cancel-label="t('btn.cancel')" @confirm="$emit('remove',tool.name)"><template #trigger><button data-action="remove-tool" :disabled="!!operating[tool.name]">{{t('btn.remove')}}</button></template></ConfirmAction></div></article><p v-if="!tools.length">{{t('custom_tools.empty')}}</p></SectionCard><div v-if="visible" class="backdrop"><form ref="dialog" role="dialog" aria-modal="true" :aria-labelledby="titleId" data-action="submit-tool" @submit.prevent="submit" @keydown="keydown"><h2 :id="titleId">{{t('custom_tools.add_title')}}</h2><label>{{t('custom_tools.form.name')}}<input ref="firstInput" v-model.trim="draft.name" data-field="tool-name" required></label><label>{{t('custom_tools.form.display_name')}}<input v-model.trim="draft.displayName" data-field="tool-display-name" required></label><label>{{t('detail.category')}}<select v-model="draft.category"><option value="language">{{t('category.language')}}</option><option value="build">{{t('category.build')}}</option><option value="mobile">{{t('category.mobile')}}</option><option value="system">{{t('category.system')}}</option><option value="package-manager">{{t('category.package-manager')}}</option></select></label><label>{{t('custom_tools.form.version')}}<input v-model.trim="draft.version" data-field="tool-version"></label><label>{{t('custom_tools.form.download_url')}}<input v-model.trim="draft.downloadUrl" data-field="tool-url" type="url" required aria-describedby="urlError?'custom-tool-url-error':undefined"></label><p v-if="urlError" id="custom-tool-url-error" role="alert">{{t(urlError)}}</p><label>{{t('custom_tools.form.shims')}}<input v-model.trim="draft.shims" data-field="tool-shims"></label><label>{{t('custom_tools.form.env_vars')}}<textarea v-model="draft.envVars" data-field="tool-env-vars"/></label><div class="actions"><button type="button" @click="close">{{t('btn.cancel')}}</button><button type="submit" :disabled="submitting||!valid">{{t('btn.add')}}</button></div></form></div></main></template>
<script setup>import{computed,nextTick,reactive,ref}from'vue';import ConfirmAction from'../components/ConfirmAction.vue';import CopyableValue from'../components/CopyableValue.vue';import PageHeader from'../components/PageHeader.vue';import SectionCard from'../components/SectionCard.vue';const props=defineProps({t:{type:Function,required:true},tools:{type:Array,default:()=>[]},operating:{type:Object,default:()=>({})},submitting:Boolean});const emit=defineEmits(['add','install','remove']);const visible=ref(false),openButton=ref(),dialog=ref(),firstInput=ref(),submitted=ref(false),titleId='custom-tool-title';const fresh=()=>({name:'',displayName:'',category:'system',version:'latest',downloadUrl:'',shims:'',envVars:''});const draft=reactive(fresh());const urlError=computed(()=>{if(!draft.downloadUrl)return'';try{return new URL(draft.downloadUrl).protocol==='https:'?'':'custom_tools.url_https'}catch{return'custom_tools.url_format'}});const valid=computed(()=>draft.name&&draft.displayName&&draft.downloadUrl&&!urlError.value);async function open(){Object.assign(draft,fresh());submitted.value=false;visible.value=true;await nextTick();firstInput.value?.focus()}async function close(){visible.value=false;await nextTick();openButton.value?.focus()}function submit(){if(!valid.value||props.submitting||submitted.value)return;submitted.value=true;emit('add',{...draft})}function keydown(event){if(event.key==='Escape'&&!props.submitting){event.preventDefault();close();return}if(event.key!=='Tab')return;const items=[...dialog.value.querySelectorAll('button,input,select,textarea')].filter(el=>!el.disabled);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}</script><style scoped>.page{display:grid;gap:16px;min-width:0}article{padding:12px;border:1px solid var(--xdev-border-subtle);overflow:hidden}.backdrop{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:16px;background:#0009}form{display:grid;gap:10px;width:min(500px,100%);max-height:calc(100vh - 32px);overflow:auto;padding:20px;box-sizing:border-box;background:var(--xdev-bg-panel);color:var(--xdev-text-primary)}label{display:grid;gap:4px}input,select,textarea{width:100%;box-sizing:border-box}.actions{display:flex;justify-content:flex-end;gap:8px}</style>
